-- Sivani Foods production schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','admin');
create type public.order_status as enum ('pending','confirmed','preparing','shipped','delivered','cancelled');
create type public.payment_status as enum ('pending','paid','failed','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role user_role not null default 'customer',created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,image_url text,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text not null,price numeric(12,2) not null check(price>=0),category_id uuid references public.categories(id) on delete restrict,image_url text,stock integer not null default 0 check(stock>=0),weight text,featured boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_name text not null,mobile text not null,email text,address text not null,city text not null,state text not null,pincode text not null,notes text,subtotal numeric(12,2) not null,delivery_charge numeric(12,2) not null default 0,total_amount numeric(12,2) not null,status order_status not null default 'pending',payment_status payment_status not null default 'pending',payment_provider text,payment_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),subtotal numeric(12,2) not null check(subtotal>=0));
create table public.order_counters(order_date date primary key,last_value integer not null default 0);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,email) values(new.id,new.email);return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger products_updated before update on products for each row execute function set_updated_at();create trigger orders_updated before update on orders for each row execute function set_updated_at();
create or replace function public.create_guest_order(p_customer jsonb,p_items jsonb,p_subtotal numeric,p_delivery_charge numeric) returns jsonb language plpgsql security definer set search_path=public as $$declare seq integer; num text; oid uuid; item jsonb; prod products%rowtype;begin if jsonb_array_length(p_items)=0 then raise exception 'Order is empty';end if;insert into order_counters(order_date,last_value) values(current_date,1) on conflict(order_date) do update set last_value=order_counters.last_value+1 returning last_value into seq;num:='SF-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(seq::text,3,'0');insert into orders(order_number,customer_name,mobile,email,address,city,state,pincode,notes,subtotal,delivery_charge,total_amount) values(num,p_customer->>'customer_name',p_customer->>'mobile',nullif(p_customer->>'email',''),p_customer->>'address',p_customer->>'city',p_customer->>'state',p_customer->>'pincode',p_customer->>'notes',p_subtotal,p_delivery_charge,p_subtotal+p_delivery_charge) returning id into oid;for item in select * from jsonb_array_elements(p_items) loop select * into prod from products where id=(item->>'product_id')::uuid and is_active for update;if not found or prod.stock<(item->>'quantity')::int or prod.price<>(item->>'unit_price')::numeric then raise exception 'Product price or stock changed';end if;insert into order_items(order_id,product_id,product_name,quantity,unit_price,subtotal) values(oid,prod.id,prod.name,(item->>'quantity')::int,prod.price,prod.price*(item->>'quantity')::int);update products set stock=stock-(item->>'quantity')::int where id=prod.id;end loop;return (select to_jsonb(o) from orders o where id=oid);end$$;
revoke all on function public.create_guest_order(jsonb,jsonb,numeric,numeric) from public,anon,authenticated;
alter table profiles enable row level security;alter table categories enable row level security;alter table products enable row level security;alter table orders enable row level security;alter table order_items enable row level security;
create policy "public reads active categories" on categories for select using(is_active);create policy "public reads active products" on products for select using(is_active);create policy "admins manage categories" on categories for all to authenticated using(is_admin()) with check(is_admin());create policy "admins manage products" on products for all to authenticated using(is_admin()) with check(is_admin());create policy "admins read orders" on orders for select to authenticated using(is_admin());create policy "admins update orders" on orders for update to authenticated using(is_admin()) with check(is_admin());create policy "admins read order items" on order_items for select to authenticated using(is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do update set file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "public reads product images" on storage.objects for select using(bucket_id='product-images');create policy "admins upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and public.is_admin());create policy "admins update product images" on storage.objects for update to authenticated using(bucket_id='product-images' and public.is_admin());create policy "admins delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and public.is_admin());
create index products_category_idx on products(category_id);create index products_active_idx on products(is_active,featured);create index orders_status_created_idx on orders(status,created_at desc);create index order_items_order_idx on order_items(order_id);
